// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto as C} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    C c;
    uint public playCount;

    function setUp() public {
        c = new C();
        playCount = 0;
    }

    function testFuzz_property(uint256 times) public {
        // Bind to a reasonable number of iterations to keep the test fast
        times = bound(times, 0, 20);

        // Deal caller enough ether for all potential play calls
        address player = address(0x1234);
        vm.deal(player, 10 ether * times);
        vm.startPrank(player);

        for (uint i = 0; i < times; i++) {
            c.play{value: 10}();
            playCount++;
        }
        vm.stopPrank();

        // The invariant: pot should be congruent to 10 * playCount (mod 2)
        // Since each play adds 10 wei (reference) before possible payout,
        // and payouts transfer all pot except fee, the pot at rest after any number
        // of calls is exactly the sum of contributed tickets that haven't been
        // paid out. The parity of the pot should match (10 * playCount) % 2 = 0.
        // The mutant adds an extra 1 wei per play, changing the parity to match
        // playCount % 2 instead.
        assertTrue(c.pot() % 2 == 0);
    }
}
